<script setup lang="ts">
import {onMounted,ref} from "vue";
import {request,type Page} from "@papilio/api";
import {faNumber} from "@papilio/ui";
import Icon from "@papilio/ui/Icon.vue";
import {useAuth} from "@papilio/auth";
const auth=useAuth();
const loading=ref(false);
const metrics=ref([{title:"Customers",description:"Registered customer accounts",icon:"users",scope:"customers",path:"/v1/admin/customers?per_page=1",value:null as number|null,error:false},{title:"Payments to review",description:"Awaiting bank-verified approval",icon:"wallet",scope:"payments",path:"/v1/admin/payments/topups?status=pending&per_page=1",value:null as number|null,error:false},{title:"Pending delivery",description:"Subscriptions awaiting provisioning",icon:"link",scope:"subscriptions",path:"/v1/admin/subscriptions?status=pending_provision&per_page=1",value:null as number|null,error:false}]);
async function load():Promise<void>{loading.value=true;const visible=metrics.value.filter(row=>auth.can(row.scope));const outcomes=await Promise.allSettled(visible.map(row=>request<Page<unknown>>(row.path)));outcomes.forEach((result,index)=>{const metric=visible[index];if(!metric)return;metric.error=result.status==='rejected';metric.value=result.status==='fulfilled'?result.value.meta.pager?.total_items??0:null;});loading.value=false;}
onMounted(load);
</script>
<template>
 <div class="page-head"><div><p class="eyebrow">YOUR WORKSPACE, AT A GLANCE</p><h1>Overview</h1><p class="subtitle">Customers, payments and delivery. One connected workspace.</p></div><button class="btn secondary" :disabled="loading" @click="load">Refresh overview</button></div>
 <div class="stats"><article v-for="metric in metrics.filter(row=>auth.can(row.scope))" :key="metric.scope" class="stat"><div class="stat-head"><span class="label">{{metric.title}}</span><span class="stat-icon"><Icon :name="metric.icon" :size="18" /></span></div><div class="value tabular">{{loading?'…':faNumber(metric.value)}}</div><p v-if="metric.error" class="message error" role="alert">Could not load this metric. Refresh to retry.</p><div class="stat-footer"><span class="hint">{{metric.description}}</span></div></article></div>
 <div class="dashboard-grid"><section class="card card-pad"><p class="eyebrow">FROM ORDER TO DELIVERY</p><h2>A clear path for every purchase</h2><div class="workflow-step"><span class="step-number">01</span><div><strong>Choose a plan and configuration bundle</strong><p>Set a quota, duration or both. Each plan can include one or more configurations with its own price.</p></div></div><div class="workflow-step"><span class="step-number">02</span><div><strong>Verify the payment</strong><p>Confirm the bank transfer in Payments. Receipts and SMS help review; they do not prove settlement.</p></div></div><div class="workflow-step"><span class="step-number">03</span><div><strong>Provision and deliver</strong><p>Follow provisioning and delivery from the subscription. Failed work remains recoverable.</p></div></div><div class="workflow-step"><span class="step-number">04</span><div><strong>Renew automatically</strong><p>Renew from the payer's wallet when enabled and funded, using the subscription's saved policy.</p></div></div></section><section class="card card-pad"><p class="eyebrow">QUICK ACCESS</p><h2>Keep things moving</h2><RouterLink v-if="auth.can('customers')" class="quick-link" to="/customers"><span><Icon name="users" />Manage customers</span><Icon name="arrow" :size="17" /></RouterLink><RouterLink v-if="auth.can('catalog')" class="quick-link" to="/plans"><span><Icon name="box" />Build a plan</span><Icon name="arrow" :size="17" /></RouterLink><RouterLink v-if="auth.can('payments')" class="quick-link" to="/payments"><span><Icon name="wallet" />Review payments</span><Icon name="arrow" :size="17" /></RouterLink><RouterLink v-if="auth.can('network')" class="quick-link" to="/network"><span><Icon name="server" />Manage infrastructure</span><Icon name="arrow" :size="17" /></RouterLink><RouterLink v-if="['payments','network','subscriptions'].some(scope=>auth.can(scope))" class="quick-link" to="/automation"><span><Icon name="bolt" />Configure automation</span><Icon name="arrow" :size="17" /></RouterLink></section></div>
</template>
